# Publish this repo's rules and skills into user-level agent config folders.
# Additive: existing non-link files/dirs are left untouched; our own links and
# generated files are refreshed. Safe to re-run anytime (e.g. after `git pull`).
#
# Run from an elevated PowerShell (Administrator) or with Developer Mode enabled
# so that creating symlinks is permitted.
$ErrorActionPreference = 'Stop'

$RepoRoot = Split-Path -Parent $PSScriptRoot
$Src = Join-Path $RepoRoot '.claude'
$ClaudeDest = Join-Path $HOME '.claude'
$CopilotSkillsDest = Join-Path $HOME '.copilot\skills'
$GeneratedMarker = 'Generated by ChekTek/ai scripts/update-config'

# VS Code's user prompts folder. Nothing is published here any more; it is still
# resolved so earlier generated files can be cleaned up.
if ($env:COPILOT_USER_PROMPTS_DIR) {
    $CopilotPromptsDest = $env:COPILOT_USER_PROMPTS_DIR
}
elseif ($env:VSCODE_USER_PROMPTS_FOLDER) {
    $CopilotPromptsDest = $env:VSCODE_USER_PROMPTS_FOLDER
}
else {
    $CopilotPromptsDest = Join-Path $env:APPDATA 'Code\User\prompts'
}

# Copilot CLI and VS Code both read ~/.copilot/instructions, so instructions are
# published there only. Writing them to the VS Code prompts folder as well makes
# every rule appear twice in VS Code.
if ($env:COPILOT_CLI_INSTRUCTIONS_DIR) {
    $CopilotCliInstructionsDest = $env:COPILOT_CLI_INSTRUCTIONS_DIR
}
else {
    $CopilotCliInstructionsDest = Join-Path $HOME '.copilot\instructions'
}

function Link-Kind {
    param(
        [string] $Dest,
        [string] $Label,
        [string] $SourceKind,
        [string] $DestKind = $SourceKind
    )

    $destKindPath = Join-Path $Dest $DestKind
    New-Item -ItemType Directory -Force $destKindPath | Out-Null

    $sourceKindPath = Join-Path $Src $SourceKind
    if (-not (Test-Path -LiteralPath $sourceKindPath -PathType Container)) { return }

    Get-ChildItem -LiteralPath $sourceKindPath | ForEach-Object {
        $target = Join-Path $destKindPath $_.Name
        $existing = Get-Item -LiteralPath $target -Force -ErrorAction SilentlyContinue

        if ($existing -and -not $existing.LinkType) {
            Write-Host "skip existing: $Label/$DestKind/$($_.Name)"
        }
        else {
            if ($existing) { Remove-Item -LiteralPath $target -Force -Recurse }
            New-Item -ItemType SymbolicLink -Path $target -Target $_.FullName | Out-Null
            Write-Host "linked: $Label/$DestKind/$($_.Name)"
        }
    }
}

function Remove-CopilotArtifactsForClaudeOnlySkills {
    $claudeOnlySkills = Join-Path $Src 'skills-claude-only'
    if (-not (Test-Path -LiteralPath $claudeOnlySkills)) { return }

    Get-ChildItem $claudeOnlySkills -Directory | ForEach-Object {
        $name = $_.Name
        $skillTarget = Join-Path $CopilotSkillsDest $name
        $existingSkill = Get-Item -LiteralPath $skillTarget -Force -ErrorAction SilentlyContinue

        if ($existingSkill -and $existingSkill.LinkType) {
            $ownedTarget = @($existingSkill.Target) | Where-Object {
                $_ -and $_.StartsWith($Src, [System.StringComparison]::OrdinalIgnoreCase)
            }
            if ($ownedTarget) {
                Remove-Item -LiteralPath $skillTarget -Force
                Write-Host "removed: copilot/skills/$name"
            }
        }
    }
}

function Remove-StaleLinks {
    param(
        [string] $Dest,
        [string] $Label,
        [string] $DestKind
    )

    $destKindPath = Join-Path $Dest $DestKind
    if (-not (Test-Path -LiteralPath $destKindPath -PathType Container)) { return }

    Get-ChildItem -LiteralPath $destKindPath -Force | ForEach-Object {
        if (-not $_.LinkType) { return }

        $ownedTarget = @($_.Target) | Where-Object {
            $_ -and $_.StartsWith($Src, [System.StringComparison]::OrdinalIgnoreCase)
        }
        if (-not $ownedTarget) { return }
        if (Test-Path -LiteralPath $ownedTarget[0]) { return }

        Remove-Item -LiteralPath $_.FullName -Force
        Write-Host "removed stale: $Label/$DestKind/$($_.Name)"
    }
}

function Remove-StaleGeneratedFiles {
    param(
        [string] $Dir,
        [string] $Label
    )

    if (-not (Test-Path -LiteralPath $Dir -PathType Container)) { return }

    Get-ChildItem -LiteralPath $Dir -Filter '*.md' -File | ForEach-Object {
        $match = Select-String -LiteralPath $_.FullName -Pattern "$([regex]::Escape($GeneratedMarker)) from (.+) -->" |
            Select-Object -First 1
        if (-not $match) { return }

        $sourceRel = $match.Matches[0].Groups[1].Value
        if (Test-Path -LiteralPath (Join-Path $RepoRoot $sourceRel)) { return }

        Remove-Item -LiteralPath $_.FullName -Force
        Write-Host "removed stale: $Label/$($_.Name)"
    }
}

# Earlier versions generated instructions and skill prompt files into the VS Code
# prompts folder. VS Code now reads ~/.copilot/instructions and ~/.copilot/skills
# natively, so those copies show up as duplicates.
function Remove-LegacyPromptFolder {
    if (-not (Test-Path -LiteralPath $CopilotPromptsDest -PathType Container)) { return }

    Get-ChildItem -LiteralPath $CopilotPromptsDest -File |
        Where-Object { $_.Name -like '*.instructions.md' -or $_.Name -like '*.prompt.md' } |
        ForEach-Object {
        if (-not (Select-String -LiteralPath $_.FullName -Pattern $GeneratedMarker -SimpleMatch -Quiet)) { return }

        Remove-Item -LiteralPath $_.FullName -Force
        Write-Host "removed duplicate: copilot prompts/$($_.Name)"
    }
}

function Test-GeneratedFileWritable {
    param([string] $Target)

    if (-not (Test-Path -LiteralPath $Target)) { return $true }
    return [bool](Select-String -LiteralPath $Target -Pattern $GeneratedMarker -SimpleMatch -Quiet)
}

function Write-GeneratedFile {
    param(
        [string] $Target,
        [string[]] $Lines,
        [string] $Label
    )

    if (-not (Test-GeneratedFileWritable $Target)) {
        Write-Host "skip existing: $Label"
        return
    }

    New-Item -ItemType Directory -Force (Split-Path -Parent $Target) | Out-Null
    $content = ($Lines -join [Environment]::NewLine) + [Environment]::NewLine
    Set-Content -LiteralPath $Target -Value $content -NoNewline -Encoding UTF8
    Write-Host "generated: $Label"
}

function Convert-RuleToInstruction {
    param([System.IO.FileInfo] $Rule)

    $rulesRoot = Join-Path $Src 'rules'
    $rulesRootPrefix = $rulesRoot.TrimEnd('\', '/') + [System.IO.Path]::DirectorySeparatorChar
    if ($Rule.FullName.StartsWith($rulesRootPrefix, [System.StringComparison]::OrdinalIgnoreCase)) {
        $relative = $Rule.FullName.Substring($rulesRootPrefix.Length)
    }
    else {
        $relative = $Rule.Name
    }
    $name = [System.IO.Path]::ChangeExtension($relative, $null).Replace('\', '-').Replace('/', '-')
    $lines = Get-Content -LiteralPath $Rule.FullName
    $descriptions = @()
    $paths = @()
    $bodyStart = 0
    $inPaths = $false

    for ($i = 1; $i -lt $lines.Count; $i++) {
        $line = $lines[$i]

        if ($line -eq '---') {
            $bodyStart = $i + 1
            break
        }

        if ($line -match '^description:') {
            $descriptions += $line
            $inPaths = $false
            continue
        }

        if ($line -match '^paths:\s*$') {
            $inPaths = $true
            continue
        }

        if ($inPaths -and $line -match '^\s*-\s*(.+)$') {
            $paths += $Matches[1]
            continue
        }

        $inPaths = $false
    }

    $output = @('---')
    $output += $descriptions
    $output += "name: `"$name`""

    if ($paths.Count -eq 1) {
        $output += "applyTo: $($paths[0])"
    }
    elseif ($paths.Count -gt 1) {
        $output += 'applyTo:'
        $output += ($paths | ForEach-Object { "    - $_" })
    }

    $output += '---'
    $output += "<!-- $GeneratedMarker from .claude/rules/$relative -->"
    $output += ''

    if ($bodyStart -lt $lines.Count) {
        $output += $lines[$bodyStart..($lines.Count - 1)]
    }

    Write-GeneratedFile (Join-Path $CopilotCliInstructionsDest "$name.instructions.md") $output `
        "copilot instructions/$name.instructions.md"
}

function Generate-CopilotInstructions {
    Get-ChildItem (Join-Path $Src 'rules') -Filter '*.md' -Recurse | ForEach-Object {
        Convert-RuleToInstruction $_
    }
}

Link-Kind $ClaudeDest claude rules
Link-Kind $ClaudeDest claude skills
Link-Kind $ClaudeDest claude skills-claude-only skills
Link-Kind (Split-Path -Parent $CopilotSkillsDest) copilot skills
Remove-CopilotArtifactsForClaudeOnlySkills
Remove-StaleLinks $ClaudeDest claude rules
Remove-StaleLinks $ClaudeDest claude skills
Remove-StaleLinks (Split-Path -Parent $CopilotSkillsDest) copilot skills
Remove-StaleGeneratedFiles $CopilotCliInstructionsDest 'copilot instructions'
Remove-LegacyPromptFolder
Generate-CopilotInstructions
